<?php
if (!defined('SCHOOLOS_FINANCE_ENGINE')) {http_response_code(403);exit;}
// Finance & Accounting v4.4.0; isolated from the main entry point.
// SchoolOS v4.2 finance: additive schema; no existing student/payment rows rewritten.
function fnReady():bool{try{return (bool)q("SHOW TABLES LIKE 'fn_invoices'")->fetchColumn();}catch(Throwable $e){return false;}}
function fnInstall():void{global $pdo;foreach([
"CREATE TABLE IF NOT EXISTS fn_fee_rules(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,class_id BIGINT UNSIGNED NOT NULL,charge_type VARCHAR(40) NOT NULL,title VARCHAR(140) NOT NULL,amount_kobo BIGINT NOT NULL,campus VARCHAR(100) NOT NULL DEFAULT '',frequency VARCHAR(20) NOT NULL DEFAULT 'term',active TINYINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,class_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS fn_invoices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,rule_id BIGINT UNSIGNED DEFAULT NULL,reference VARCHAR(90) NOT NULL,description VARCHAR(190) NOT NULL,campus VARCHAR(100) NOT NULL DEFAULT '',session_name VARCHAR(80) NOT NULL DEFAULT '',term_name VARCHAR(80) NOT NULL DEFAULT '',amount_kobo BIGINT NOT NULL,discount_kobo BIGINT NOT NULL DEFAULT 0,penalty_kobo BIGINT NOT NULL DEFAULT 0,paid_kobo BIGINT NOT NULL DEFAULT 0,due_date DATE DEFAULT NULL,status VARCHAR(20) NOT NULL DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY ref_tenant(tenant_id,reference),INDEX(tenant_id,student_id),INDEX(tenant_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS fn_payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,invoice_id BIGINT UNSIGNED NOT NULL,reference VARCHAR(100) NOT NULL,amount_kobo BIGINT NOT NULL,channel VARCHAR(35) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',notes VARCHAR(250) NOT NULL DEFAULT '',confirmed_by BIGINT UNSIGNED DEFAULT NULL,confirmed_at DATETIME DEFAULT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY ref_unique(reference),INDEX(tenant_id,invoice_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS fn_journal(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,entry_ref VARCHAR(110) NOT NULL,account_code VARCHAR(20) NOT NULL,debit_kobo BIGINT NOT NULL DEFAULT 0,credit_kobo BIGINT NOT NULL DEFAULT 0,campus VARCHAR(100) NOT NULL DEFAULT '',memo VARCHAR(250) NOT NULL DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_entry(tenant_id,entry_ref,account_code),INDEX(tenant_id,account_code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS fn_expenses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,supplier VARCHAR(160) NOT NULL,category VARCHAR(70) NOT NULL,description VARCHAR(250) NOT NULL,amount_kobo BIGINT NOT NULL,campus VARCHAR(100) NOT NULL DEFAULT '',status VARCHAR(25) NOT NULL DEFAULT 'pending',reference VARCHAR(100) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED DEFAULT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY expense_ref(tenant_id,reference),INDEX(tenant_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS fn_budgets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,category VARCHAR(70) NOT NULL,campus VARCHAR(100) NOT NULL DEFAULT '',period VARCHAR(30) NOT NULL,amount_kobo BIGINT NOT NULL,UNIQUE KEY budget_scope(tenant_id,category,campus,period)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS fn_credits(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,amount_kobo BIGINT NOT NULL,reason VARCHAR(180) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS fn_refunds(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,payment_id BIGINT UNSIGNED NOT NULL,amount_kobo BIGINT NOT NULL,reason VARCHAR(200) NOT NULL,status VARCHAR(25) NOT NULL DEFAULT 'requested',created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,payment_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS fn_reminders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,invoice_id BIGINT UNSIGNED NOT NULL,recipient VARCHAR(190) NOT NULL,channel VARCHAR(20) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,invoice_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
] as $sql)$pdo->exec($sql);}
function fnMoney($raw):int{if(!preg_match('/^\\d{1,11}(?:\\.\\d{1,2})?$/D',trim((string)$raw)))throw new RuntimeException('Enter a valid positive naira amount.');$p=explode('.',trim((string)$raw));$k=(int)$p[0]*100+(int)str_pad($p[1]??'0',2,'0');if($k<=0||$k>100000000000)throw new RuntimeException('Amount outside supported range.');return $k;}
function fnFmt($k):string{return '₦'.number_format((int)$k/100,2);}
function fnText($k,$max=150):string{return mb_substr(trim((string)($_POST[$k]??'')),0,$max);}
function fnOwnStudent($tid,$id):bool{return (bool)g('SELECT id FROM students WHERE tenant_id=? AND id=?',[$tid,$id]);}
function fnJournal($tid,$ref,$debit,$credit,$amount,$campus,$memo):void{if($amount<=0||$debit===$credit)throw new RuntimeException('Invalid journal entry.');q('INSERT INTO fn_journal(tenant_id,entry_ref,account_code,debit_kobo,campus,memo) VALUES(?,?,?,?,?,?)',[$tid,$ref,$debit,$amount,$campus,$memo]);q('INSERT INTO fn_journal(tenant_id,entry_ref,account_code,credit_kobo,campus,memo) VALUES(?,?,?,?,?,?)',[$tid,$ref,$credit,$amount,$campus,$memo]);}
function fnCreditBalance($tid,$sid):int{return (int)g('SELECT COALESCE(SUM(amount_kobo),0) FROM fn_credits WHERE tenant_id=? AND student_id=?',[$tid,$sid]);}
function fnUseCredit($tid,$invoiceId,$amount,$actor):void{global $pdo;$i=q('SELECT * FROM fn_invoices WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$invoiceId])->fetch();if(!$i)throw new RuntimeException('Invoice not found.');$due=max(0,(int)$i['amount_kobo']-(int)$i['discount_kobo']+(int)$i['penalty_kobo']-(int)$i['paid_kobo']);if($amount>$due)throw new RuntimeException('Credit allocation exceeds the invoice balance.');if(fnCreditBalance($tid,(int)$i['student_id'])<$amount)throw new RuntimeException('Insufficient student credit.');$ref='CREDIT-'.bin2hex(random_bytes(12));q('INSERT INTO fn_credits(tenant_id,student_id,amount_kobo,reason,created_by) VALUES(?,?,?,?,?)',[$tid,$i['student_id'],-$amount,'Applied to '.$i['reference'],$actor]);q("INSERT INTO fn_payments(tenant_id,invoice_id,reference,amount_kobo,channel,status,notes,confirmed_by,confirmed_at) VALUES(?,?,?,?,?,'confirmed',?,?,NOW())",[$tid,$invoiceId,$ref,$amount,'credit','Credit balance allocation',$actor]);fnJournal($tid,$ref,'2100','1100',$amount,$i['campus'],'Student credit applied');fnRefresh($tid,$invoiceId);}
function fnRefresh($tid,$id):void{$i=q('SELECT * FROM fn_invoices WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$id])->fetch();if(!$i)throw new RuntimeException('Invoice not found.');$paid=(int)g("SELECT COALESCE(SUM(amount_kobo),0) FROM fn_payments WHERE tenant_id=? AND invoice_id=? AND status='confirmed'",[$tid,$id]);$due=max(0,(int)$i['amount_kobo']-(int)$i['discount_kobo']+(int)$i['penalty_kobo']);q('UPDATE fn_invoices SET paid_kobo=?,status=? WHERE tenant_id=? AND id=?',[min($paid,$due),$paid>=$due?'paid':($paid>0?'partial':'open'),$tid,$id]);}
function fnConfirmPayment($tid,$id,$actor):void{global $pdo;$p=q('SELECT p.*,i.campus FROM fn_payments p JOIN fn_invoices i ON i.id=p.invoice_id AND i.tenant_id=p.tenant_id WHERE p.tenant_id=? AND p.id=? FOR UPDATE',[$tid,$id])->fetch();if(!$p)throw new RuntimeException('Payment not found.');if($p['status']==='confirmed')return;if($p['status']!=='pending')throw new RuntimeException('Payment cannot be confirmed.');$inv=q('SELECT * FROM fn_invoices WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$p['invoice_id']])->fetch();$balance=(int)$inv['amount_kobo']-(int)$inv['discount_kobo']+(int)$inv['penalty_kobo']-(int)$inv['paid_kobo'];if($balance<=0)throw new RuntimeException('Invoice is already settled.');$allocation=min((int)$p['amount_kobo'],$balance);$surplus=(int)$p['amount_kobo']-$allocation;if($surplus>0){q('INSERT INTO fn_credits(tenant_id,student_id,amount_kobo,reason,created_by) VALUES(?,?,?,?,?)',[$tid,$inv['student_id'],$surplus,'Excess payment '.$p['reference'],$actor]);}q("UPDATE fn_payments SET status='confirmed',confirmed_by=?,confirmed_at=NOW() WHERE id=? AND tenant_id=?",[$actor,$id,$tid]);fnJournal($tid,'PAY-'.$id,'1000','1100',$allocation,$p['campus'],'Payment '.$p['reference']);if($surplus>0)fnJournal($tid,'ADV-'.$id,'1000','2100',$surplus,$p['campus'],'Student advance '.$p['reference']);fnRefresh($tid,(int)$p['invoice_id']);}

function fn45Install():void {global $pdo;
 foreach([
 "CREATE TABLE IF NOT EXISTS fn45_settings(tenant_id BIGINT UNSIGNED PRIMARY KEY,paystack_secret TEXT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS fn45_recurring(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,rule_id BIGINT UNSIGNED NOT NULL,next_due DATE NOT NULL,frequency VARCHAR(12) NOT NULL,active TINYINT NOT NULL DEFAULT 1,last_run DATETIME NULL,UNIQUE KEY tenant_rule(tenant_id,rule_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS fn45_gateway(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,invoice_id BIGINT UNSIGNED NOT NULL,reference VARCHAR(110) NOT NULL,amount_kobo BIGINT NOT NULL,authorization_url TEXT NULL,status VARCHAR(25) NOT NULL DEFAULT 'pending',verified_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY gateway_ref(reference),INDEX(tenant_id,invoice_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
 ] as $sql)$pdo->exec($sql);
}
function fn45Api(string $method,string $path,string $secret,?array $payload=null):array {if(defined('SCHOOLOS_DEMO_MODE'))throw new RuntimeException('External providers are disabled in the demo.');
 if(!function_exists('curl_init'))throw new RuntimeException('Server PHP cURL extension is required.');
 $ch=curl_init('https://api.paystack.co'.$path);$headers=['Authorization: Bearer '.$secret,'Accept: application/json'];
 if($payload!==null){$headers[]='Content-Type: application/json';curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($payload,JSON_THROW_ON_ERROR));}
 curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>20,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_HTTPHEADER=>$headers,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_CUSTOMREQUEST=>$method]);
 $response=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_error($ch);curl_close($ch);
 if($response===false)throw new RuntimeException('Payment provider unavailable: '.$err);
 $data=json_decode($response,true);if(!is_array($data)||$code<200||$code>=300||empty($data['status']))throw new RuntimeException('Paystack request failed: '.mb_substr((string)($data['message']??'HTTP '.$code),0,160));return $data;
}
function fn45Secret(int $tid):string {$s=(string)g('SELECT paystack_secret FROM fn45_settings WHERE tenant_id=?',[$tid]);if(!preg_match('/^sk_(test|live)_[A-Za-z0-9]+$/D',$s))throw new RuntimeException('Configure this school’s Paystack secret key first.');return $s;}
function fn45RunRecurring(int $tid):int {global $pdo;$rows=q('SELECT r.*,f.class_id,f.title,f.amount_kobo,f.campus FROM fn45_recurring r JOIN fn_fee_rules f ON f.id=r.rule_id AND f.tenant_id=r.tenant_id WHERE r.tenant_id=? AND r.active=1 AND r.next_due<=CURRENT_DATE() FOR UPDATE',[$tid])->fetchAll();$created=0;
 foreach($rows as $r){$due=new DateTimeImmutable($r['next_due']);$today=new DateTimeImmutable('today');$loops=0;while($due<=$today&&$loops++<36){$period=$due->format('Y-m-d');$students=q('SELECT id FROM students WHERE tenant_id=? AND class_id=?',[$tid,$r['class_id']])->fetchAll();foreach($students as $st){$ref='FEE-'.$tid.'-'.$r['rule_id'].'-'.$st['id'].'-'.substr(hash('sha256',$period),0,12);if(g('SELECT id FROM fn_invoices WHERE tenant_id=? AND reference=?',[$tid,$ref]))continue;q('INSERT INTO fn_invoices(tenant_id,student_id,rule_id,reference,description,campus,session_name,amount_kobo,due_date) VALUES(?,?,?,?,?,?,?,?,?)',[$tid,$st['id'],$r['rule_id'],$ref,$r['title'],$r['campus'],$period,$r['amount_kobo'],$period]);fnJournal($tid,'INV-'.(int)$pdo->lastInsertId(),'1100','4100',(int)$r['amount_kobo'],$r['campus'],'Recurring invoice '.$ref);$created++;}$due=$due->modify($r['frequency']==='monthly'?'+1 month':($r['frequency']==='annual'?'+1 year':'+3 months'));}q('UPDATE fn45_recurring SET next_due=?,last_run=NOW() WHERE tenant_id=? AND id=?',[$due->format('Y-m-d'),$tid,$r['id']]);}return $created;
}

if(isset($_POST['fn_action'])&&me()){
 $fnNotice='';$fnTid=(int)me()['tenant_id'];$fnActor=(int)me()['id'];
 try{if(me()['role']!=='school_admin')throw new RuntimeException('School administrator access required.');if(!hash_equals($_SESSION['csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Security token expired.');$act=fnText('fn_action',40);
 if($act==='activate'){fnInstall();$fnNotice='Finance workspace activated.';}
 else{if(!fnReady())throw new RuntimeException('Activate finance first.');if($act==='finance_upgrade'){fn45Install();$fnNotice='Finance integrations prepared. Existing records preserved.';}else{global $pdo;$pdo->beginTransaction();
 if($act==='rule'){$cid=(int)($_POST['class_id']??0);if(!g('SELECT id FROM classes WHERE tenant_id=? AND id=?',[$fnTid,$cid]))throw new RuntimeException('Select a valid class.');$type=fnText('charge_type',40);if(!in_array($type,['tuition','transport','meals','hostel','other'],true))throw new RuntimeException('Invalid charge category.');$title=fnText('title');if(strlen($title)<3)throw new RuntimeException('Provide a fee title.');q('INSERT INTO fn_fee_rules(tenant_id,class_id,charge_type,title,amount_kobo,campus,frequency) VALUES(?,?,?,?,?,?,?)',[$fnTid,$cid,$type,$title,fnMoney($_POST['amount']??''),fnText('campus',100),in_array(fnText('frequency'),['term','monthly','annual','one_time'],true)?fnText('frequency'):'term']);$fnNotice='Fee rule saved.';}
 elseif($act==='invoice'||$act==='generate'){$sid=(int)($_POST['student_id']??0);$rid=(int)($_POST['rule_id']??0);$rule=q('SELECT * FROM fn_fee_rules WHERE tenant_id=? AND id=? AND active=1',[$fnTid,$rid])->fetch();if(!$rule)throw new RuntimeException('Select a fee rule.');$students=$act==='generate'?q('SELECT id FROM students WHERE tenant_id=? AND class_id=?',[$fnTid,$rule['class_id']])->fetchAll():[['id'=>$sid]];$created=0;$period=fnText('period',80);if($period==='')throw new RuntimeException('Enter the term or billing period.');foreach($students as $student){$studentId=(int)$student['id'];if(!fnOwnStudent($fnTid,$studentId))continue;$ref='FEE-'.$fnTid.'-'.$rid.'-'.$studentId.'-'.substr(hash('sha256',$period),0,12);if(g('SELECT id FROM fn_invoices WHERE tenant_id=? AND reference=?',[$fnTid,$ref]))continue;$due=fnText('due_date',20);if($due!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$due))throw new RuntimeException('Invalid due date.');q('INSERT INTO fn_invoices(tenant_id,student_id,rule_id,reference,description,campus,session_name,amount_kobo,due_date) VALUES(?,?,?,?,?,?,?,?,?)',[$fnTid,$studentId,$rid,$ref,$rule['title'],$rule['campus'],$period,$rule['amount_kobo'],$due?:null]);fnJournal($fnTid,'INV-'.(int)$pdo->lastInsertId(),'1100','4100',(int)$rule['amount_kobo'],$rule['campus'],'Fee invoice '.$ref);$created++;} $fnNotice=$created.' invoice(s) generated. Existing invoices for this period were skipped.';}
 elseif($act==='adjust'){$id=(int)($_POST['invoice_id']??0);$i=q('SELECT * FROM fn_invoices WHERE tenant_id=? AND id=? FOR UPDATE',[$fnTid,$id])->fetch();if(!$i)throw new RuntimeException('Invoice not found.');$kind=fnText('kind',20);$amt=fnMoney($_POST['amount']??'');if($kind==='discount'||$kind==='scholarship'){if($amt>(int)$i['amount_kobo']-(int)$i['discount_kobo'])throw new RuntimeException('Discount exceeds remaining charges.');q('UPDATE fn_invoices SET discount_kobo=discount_kobo+? WHERE id=? AND tenant_id=?',[$amt,$id,$fnTid]);}elseif($kind==='penalty'){q('UPDATE fn_invoices SET penalty_kobo=penalty_kobo+? WHERE id=? AND tenant_id=?',[$amt,$id,$fnTid]);}else throw new RuntimeException('Invalid adjustment.');fnJournal($fnTid,'ADJ-'.$id.'-'.bin2hex(random_bytes(5)),$kind==='penalty'?'1100':'4200',$kind==='penalty'?'4100':'1100',$amt,$i['campus'],'Invoice '.$kind);fnRefresh($fnTid,$id);audit('finance.adjustment','invoice',$kind.' '.$id.' '.fnFmt($amt));$fnNotice='Invoice adjustment recorded.';}
 elseif($act==='payment'){$id=(int)($_POST['invoice_id']??0);$i=q('SELECT * FROM fn_invoices WHERE tenant_id=? AND id=?',[$fnTid,$id])->fetch();if(!$i)throw new RuntimeException('Invoice not found.');$amt=fnMoney($_POST['amount']??'');$ref=fnText('reference',100);if(strlen($ref)<5)throw new RuntimeException('Enter the bank/payment reference.');$channel=fnText('channel',30);if(!in_array($channel,['bank_transfer','cash','pos'],true))throw new RuntimeException('Choose a payment channel.');q('INSERT INTO fn_payments(tenant_id,invoice_id,reference,amount_kobo,channel,notes) VALUES(?,?,?,?,?,?)',[$fnTid,$id,$ref,$amt,$channel,fnText('notes',240)]);$fnNotice='Payment submitted for reconciliation. It is not yet confirmed.';}
 elseif($act==='confirm'){$id=(int)($_POST['payment_id']??0);fnConfirmPayment($fnTid,$id,$fnActor);audit('finance.payment.confirm','payment',(string)$id);$fnNotice='Payment confirmed and ledger posted.';}
 elseif($act==='expense'){$supplier=fnText('supplier');$category=fnText('category',70);if(strlen($supplier)<2||strlen($category)<2)throw new RuntimeException('Supplier and category required.');$ref='EXP-'.bin2hex(random_bytes(9));q('INSERT INTO fn_expenses(tenant_id,supplier,category,description,amount_kobo,campus,reference,created_by) VALUES(?,?,?,?,?,?,?,?)',[$fnTid,$supplier,$category,fnText('description',240),fnMoney($_POST['amount']??''),fnText('campus',100),$ref,$fnActor]);$fnNotice='Supplier expense awaiting approval.';}
 elseif($act==='expense_approve'){$id=(int)($_POST['expense_id']??0);$e=q('SELECT * FROM fn_expenses WHERE tenant_id=? AND id=? FOR UPDATE',[$fnTid,$id])->fetch();if(!$e||$e['status']!=='pending')throw new RuntimeException('Expense not pending.');q("UPDATE fn_expenses SET status='paid',approved_by=? WHERE tenant_id=? AND id=?",[$fnActor,$fnTid,$id]);fnJournal($fnTid,'EXP-'.$id,'5100','1000',(int)$e['amount_kobo'],$e['campus'],'Supplier: '.$e['supplier']);$fnNotice='Expense approved and recorded as paid.';}
 elseif($act==='budget'){$category=fnText('category',70);$period=fnText('period',30);if(!$category||!$period)throw new RuntimeException('Category and budget period required.');q('INSERT INTO fn_budgets(tenant_id,category,campus,period,amount_kobo) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE amount_kobo=VALUES(amount_kobo)',[$fnTid,$category,fnText('campus',100),$period,fnMoney($_POST['amount']??'')]);$fnNotice='Budget saved.';}
 elseif($act==='refund'){$pid=(int)($_POST['payment_id']??0);$p=q("SELECT * FROM fn_payments WHERE tenant_id=? AND id=? AND status='confirmed'",[$fnTid,$pid])->fetch();if(!$p)throw new RuntimeException('Select a confirmed payment.');$amt=fnMoney($_POST['amount']??'');$used=(int)g("SELECT COALESCE(SUM(amount_kobo),0) FROM fn_refunds WHERE tenant_id=? AND payment_id=? AND status IN ('requested','approved','paid')",[$fnTid,$pid]);if($amt+$used>(int)$p['amount_kobo'])throw new RuntimeException('Refund exceeds payment.');q('INSERT INTO fn_refunds(tenant_id,payment_id,amount_kobo,reason,created_by) VALUES(?,?,?,?,?)',[$fnTid,$pid,$amt,fnText('reason',190),$fnActor]);$fnNotice='Refund request logged; money has not been sent.';}
 elseif($act==='credit_apply'){$invoiceId=(int)($_POST['invoice_id']??0);$amount=fnMoney($_POST['amount']??'');fnUseCredit($fnTid,$invoiceId,$amount,$fnActor);audit('finance.credit.allocate','invoice',(string)$invoiceId);$fnNotice='Student credit applied to invoice and journal posted.';}
 elseif($act==='refund_paid'){$rid=(int)($_POST['refund_id']??0);$ref=q("SELECT r.*,p.invoice_id,i.campus,i.student_id FROM fn_refunds r JOIN fn_payments p ON p.id=r.payment_id AND p.tenant_id=r.tenant_id JOIN fn_invoices i ON i.id=p.invoice_id AND i.tenant_id=p.tenant_id WHERE r.tenant_id=? AND r.id=? FOR UPDATE",[$fnTid,$rid])->fetch();if(!$ref||$ref['status']!=='requested')throw new RuntimeException('Refund request unavailable.');$original=q('SELECT * FROM fn_payments WHERE tenant_id=? AND id=?',[$fnTid,$ref['payment_id']])->fetch();if(!$original||$original['channel']==='credit')throw new RuntimeException('Credit allocations cannot be refunded as cash.');$proof=fnText('bank_reference',100);if(strlen($proof)<6)throw new RuntimeException('Provide a verified outgoing bank reference.');q("UPDATE fn_refunds SET status='paid',reason=CONCAT(reason,' | Bank ref: ',?) WHERE tenant_id=? AND id=?",[$proof,$fnTid,$rid]);fnJournal($fnTid,'REF-'.$rid,'1100','1000',(int)$ref['amount_kobo'],$ref['campus'],'Refund paid: '.$proof);fnRefresh($fnTid,(int)$ref['invoice_id']);audit('finance.refund.paid','refund',(string)$rid);$fnNotice='Refund recorded as paid and ledger reversed. Verify bank reference independently.';}
 elseif($act==='reminder'){$id=(int)($_POST['invoice_id']??0);$i=q('SELECT i.*,s.phone FROM fn_invoices i JOIN students s ON s.id=i.student_id AND s.tenant_id=i.tenant_id WHERE i.tenant_id=? AND i.id=?',[$fnTid,$id])->fetch();if(!$i)throw new RuntimeException('Invoice not found.');$phone=preg_replace('/\D+/','',(string)$i['phone']);if(strlen($phone)===11&&$phone[0]==='0')$phone='234'.substr($phone,1);if(strlen($phone)<10)throw new RuntimeException('No usable phone number on student record.');q('INSERT INTO fn_reminders(tenant_id,invoice_id,recipient,channel,created_by) VALUES(?,?,?,?,?)',[$fnTid,$id,$phone,'whatsapp',$fnActor]);$_SESSION['fn_whatsapp']='https://wa.me/'.$phone.'?text='.rawurlencode('School fee reminder: invoice '.$i['reference'].' has an outstanding balance of '.fnFmt(max(0,(int)$i['amount_kobo']-(int)$i['discount_kobo']+(int)$i['penalty_kobo']-(int)$i['paid_kobo'])).'. Please contact the school accounts office.');$fnNotice='WhatsApp reminder prepared. You must click Send in WhatsApp.';}
 elseif($act==='paystack_settings'){$secret=fnText('secret_key',190);if(!preg_match('/^sk_(test|live)_[A-Za-z0-9]+$/D',$secret))throw new RuntimeException('Use a valid Paystack secret key.');q('INSERT INTO fn45_settings(tenant_id,paystack_secret) VALUES(?,?) ON DUPLICATE KEY UPDATE paystack_secret=VALUES(paystack_secret)',[$fnTid,$secret]);audit('finance.paystack.settings','tenant',(string)$fnTid);$fnNotice='School Paystack key saved. Do not share secret keys in screenshots.';}
