 elseif($act==='recurring_run'){$created=fn45RunRecurring($fnTid);audit('finance.recurring.run','invoice',(string)$created);$fnNotice=$created.' new invoices generated. Existing invoices were not duplicated.';}
 elseif($act==='paystack_initialize'){$id=(int)($_POST['invoice_id']??0);$i=q('SELECT i.*,s.name,s.email FROM fn_invoices i JOIN students s ON s.id=i.student_id AND s.tenant_id=i.tenant_id WHERE i.tenant_id=? AND i.id=? FOR UPDATE',[$fnTid,$id])->fetch();if(!$i)throw new RuntimeException('Invoice not found.');$balance=(int)$i['amount_kobo']-(int)$i['discount_kobo']+(int)$i['penalty_kobo']-(int)$i['paid_kobo'];if($balance<=0)throw new RuntimeException('Invoice already settled.');$email=trim((string)($i['email']??''));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Student email is missing or invalid.');$ref='SOS-'.$fnTid.'-'.$id.'-'.bin2hex(random_bytes(10));$resp=fn45Api('POST','/transaction/initialize',fn45Secret($fnTid),['email'=>$email,'amount'=>$balance,'reference'=>$ref,'currency'=>'NGN','metadata'=>['tenant_id'=>$fnTid,'invoice_id'=>$id]]);$url=(string)($resp['data']['authorization_url']??'');if(!preg_match('~^https://checkout\.paystack\.com/~',$url))throw new RuntimeException('Unexpected checkout address.');q('INSERT INTO fn45_gateway(tenant_id,invoice_id,reference,amount_kobo,authorization_url) VALUES(?,?,?,?,?)',[$fnTid,$id,$ref,$balance,$url]);$_SESSION['fn45_checkout']=$url;$fnNotice='Secure checkout created. Open it below to complete payment.';}
 elseif($act==='paystack_verify'){$gid=(int)($_POST['gateway_id']??0);$gw=q('SELECT * FROM fn45_gateway WHERE tenant_id=? AND id=? FOR UPDATE',[$fnTid,$gid])->fetch();if(!$gw)throw new RuntimeException('Transaction not found.');if($gw['status']==='confirmed'){$fnNotice='Payment already verified.';}else{$resp=fn45Api('GET','/transaction/verify/'.rawurlencode($gw['reference']),fn45Secret($fnTid));$data=$resp['data']??[];if(($data['status']??'')!=='success'||(string)($data['reference']??'')!==$gw['reference']||(int)($data['amount']??-1)!==(int)$gw['amount_kobo']||strtoupper((string)($data['currency']??''))!=='NGN')throw new RuntimeException('Provider has not confirmed the expected payment amount and reference.');$provider=(string)($data['gateway_response']??'Paystack verified');q("INSERT INTO fn_payments(tenant_id,invoice_id,reference,amount_kobo,channel,status,notes) VALUES(?,?,?,?,?,'pending',?)",[$fnTid,$gw['invoice_id'],$gw['reference'],$gw['amount_kobo'],'paystack',mb_substr($provider,0,240)]);$pid=(int)$pdo->lastInsertId();fnConfirmPayment($fnTid,$pid,$fnActor);q("UPDATE fn45_gateway SET status='confirmed',verified_at=NOW() WHERE tenant_id=? AND id=?",[$fnTid,$gid]);audit('finance.paystack.verified','payment',(string)$pid);$fnNotice='Paystack transaction verified and posted.';}}
 else throw new RuntimeException('Unsupported finance action.');$pdo->commit();}}
